import java.io.*;
import java.util.*;

public class Main {
    public static class Task {
        // Use a single class for both flows with static methods
        static class Flow {
            static class Edge {
                int to, rev, cap, flow, cost;
                Edge(int to, int rev, int cap, int cost) {
                    this.to = to; this.rev = rev; this.cap = cap; this.cost = cost;
                }
            }
            static List<Edge>[] graph;
            static int n;

            static void init(int n) {
                Flow.n = n;
                graph = new List[n];
                for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
            }
            static void addEdge(int s, int t, int cap, int cost) {
                graph[s].add(new Edge(t, graph[t].size(), cap, cost));
                graph[t].add(new Edge(s, graph[s].size() - 1, 0, -cost));
            }

            // Dinic
            static boolean bfs(int s, int t, int[] d) {
                Arrays.fill(d, -1);
                d[s] = 0;
                int[] q = new int[n];
                int qs = 0;
                q[qs++] = s;
                for (int i = 0; i < qs; i++) {
                    int u = q[i];
                    for (Edge e : graph[u]) {
                        if (d[e.to] < 0 && e.flow < e.cap) {
                            d[e.to] = d[u] + 1;
                            q[qs++] = e.to;
                        }
                    }
                }
                return d[t] >= 0;
            }
            static long dfs(int[] ptr, int[] d, int t, int u, long f) {
                if (u == t) return f;
                for (; ptr[u] < graph[u].size(); ++ptr[u]) {
                    Edge e = graph[u].get(ptr[u]);
                    if (d[e.to] == d[u] + 1 && e.flow < e.cap) {
                        long df = dfs(ptr, d, t, e.to, Math.min(f, e.cap - e.flow));
                        if (df > 0) {
                            e.flow += df;
                            graph[e.to].get(e.rev).flow -= df;
                            return df;
                        }
                    }
                }
                return 0;
            }
            static long maxFlow(int s, int t) {
                long flow = 0;
                int[] d = new int[n];
                while (bfs(s, t, d)) {
                    int[] ptr = new int[n];
                    while (true) {
                        long df = dfs(ptr, d, t, s, Long.MAX_VALUE);
                        if (df == 0) break;
                        flow += df;
                    }
                }
                return flow;
            }

            // Min-cost flow
            static void bellmanFord(int s, int[] dist, int[] prevNode, int[] prevEdge, int[] curFlow) {
                Arrays.fill(dist, 0, n, Integer.MAX_VALUE);
                dist[s] = 0;
                curFlow[s] = Integer.MAX_VALUE;
                boolean[] inQ = new boolean[n];
                int[] q = new int[n];
                int qt = 0;
                q[qt++] = s;
                for (int qh = 0; (qh - qt) % n != 0; qh++) {
                    int u = q[qh % n];
                    inQ[u] = false;
                    for (int i = 0; i < graph[u].size(); i++) {
                        Edge e = graph[u].get(i);
                        if (e.flow >= e.cap) continue;
                        int v = e.to;
                        int nd = dist[u] + e.cost;
                        if (dist[v] > nd) {
                            dist[v] = nd;
                            prevNode[v] = u;
                            prevEdge[v] = i;
                            curFlow[v] = Math.min(curFlow[u], e.cap - e.flow);
                            if (!inQ[v]) {
                                inQ[v] = true;
                                q[qt++ % n] = v;
                            }
                        }
                    }
                }
            }
            static int[] minCostFlow(int s, int t, int maxf) {
                int[] dist = new int[n];
                int[] curFlow = new int[n];
                int[] prevEdge = new int[n];
                int[] prevNode = new int[n];
                int flow = 0, cost = 0;
                while (flow < maxf) {
                    bellmanFord(s, dist, prevNode, prevEdge, curFlow);
                    if (dist[t] == Integer.MAX_VALUE) break;
                    int df = Math.min(curFlow[t], maxf - flow);
                    flow += df;
                    for (int v = t; v != s; v = prevNode[v]) {
                        Edge e = graph[prevNode[v]].get(prevEdge[v]);
                        e.flow += df;
                        graph[v].get(e.rev).flow -= df;
                        cost += df * e.cost;
                    }
                }
                return new int[]{flow, cost};
            }
        }

        public void solve(Scanner sc, PrintWriter pw) throws IOException {
            int N = sc.nextInt();
            int M = sc.nextInt();
            int K = sc.nextInt();
            int C = sc.nextInt();
            int D = sc.nextInt();
            int[] pos = new int[N];
            for (int i = 0; i < K; i++) pos[sc.nextInt() - 1]++;
            int T = 100;
            Flow.init((T + 1) * N + 2);
            for (int i = 0; i < N; i++) if (pos[i] > 0) Flow.addEdge(0, i + 1, pos[i], 0);
            for (int i = 0; i < T; i++) for (int j = 0; j < N; j++) Flow.addEdge(1 + i * N + j, 1 + (i + 1) * N + j, K, 0);
            for (int i = 0; i <= T; i++) for (int j = 1; j <= K; j++) Flow.addEdge(1 + i * N, (T + 1) * N + 1, 1, C * i);
            for (int i = 0; i < M; i++) {
                int a = sc.nextInt() - 1, b = sc.nextInt() - 1;
                for (int j = 0; j < T; j++) {
                    int cost = 0;
                    for (int l = 1; l <= K; l++) {
                        Flow.addEdge(1 + j * N + a, 1 + (j + 1) * N + b, 1, l * l * D - cost);
                        Flow.addEdge(1 + j * N + b, 1 + (j + 1) * N + a, 1, l * l * D - cost);
                        cost = l * l * D;
                    }
                }
            }
            int[] res = Flow.minCostFlow(0, (T + 1) * N + 1, K);
            System.err.println(res[0]);
            pw.println(res[1]);
        }
    }

    static long TIME_START, TIME_END;

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(new BufferedOutputStream(System.out));
        Runtime rt = Runtime.getRuntime();
        long memBefore = rt.totalMemory() - rt.freeMemory();
        TIME_START = System.currentTimeMillis();
        new Task().solve(sc, pw);
        TIME_END = System.currentTimeMillis();
        long memAfter = rt.totalMemory() - rt.freeMemory();
        pw.close();
        System.err.println("Memory increased: " + (memAfter - memBefore) / 1000000);
        System.err.println("Time used: " + (TIME_END - TIME_START) + ".");
    }

    static class Scanner {
        StringTokenizer st;
        BufferedReader br;
        Scanner(InputStream s) { br = new BufferedReader(new InputStreamReader(s)); }
        Scanner(FileReader s) throws FileNotFoundException { br = new BufferedReader(s); }
        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) st = new StringTokenizer(br.readLine());
            return st.nextToken();
        }
        int nextInt() throws IOException { return Integer.parseInt(next()); }
        long nextLong() throws IOException { return Long.parseLong(next()); }
        String nextLine() throws IOException { return br.readLine(); }
        double nextDouble() throws IOException { return Double.parseDouble(next()); }
        boolean ready() throws IOException { return br.ready(); }
    }
}
